            {initialPaidMethod==='cliq'&&<label className="block space-y-2 text-sm" htmlFor="pos-initial-reference"><span className="block">مرجع CliQ (اختياري)</span>
              <input id="pos-initial-reference" value={initialPaidReference} maxLength={200} enterKeyHint="done" onChange={event=>setInitialPaidReference(event.target.value)}
                className="block min-h-11 w-full rounded-xl border border-nw-border bg-nw-surface px-3 py-2 text-base text-nw-text"/>
            </label>}
            <p id="pos-initial-paid-help" className={initialPaidIssue?'text-sm text-nw-bad':'text-sm text-nw-muted'} role={initialPaidIssue?'alert':undefined}>
              {initialPaidIssue??<>الباقي على الحساب: <MoneyText amount={initialDue??totalAmount} currency/>. صفر يعني ديناً كاملاً؛ دفع الصافي كله يعني دفعاً كاملاً.</>}
            </p>
          </fieldset>}

                      {/* Received Cash Input */}
          {paymentMethod === 'cash' && cartItems.length > 0 && (
            <div className="flex items-center justify-between bg-nw-surface-2/80 p-2.5 rounded-xl border border-nw-border">
              <div>
                <span className="text-[11px] text-nw-text font-bold block">المبلغ المستلم:</span>
                <span className="text-[10px] text-nw-ok">الباقي: {changeDue.toFixed(3)} {CURRENCY}</span>
              </div>
              <input inputMode="decimal" enterKeyHint="done" aria-label="المبلغ المستلم"
                type="number"
                value={cashReceived || ''}
                onChange={(e) => setCashReceived(parseFloat(e.target.value) || 0)}
                placeholder={totalAmount.toFixed(3)}
                className="min-h-11 w-28 bg-nw-surface border border-nw-border rounded-lg px-2 py-1 text-left font-bold text-nw-text text-xs focus:outline-none focus:border-nw-ok"
              />
            </div>
          )}


          </ResponsiveCartPanel>
        </div>
      </div>
      <StickyActionBar tone="hero" hidden={isCartOpen} data-testid="pos-sticky-checkout">
        <div className="flex min-w-0 items-center justify-between gap-2">
          <strong className="text-xl"><MoneyText amount={totalAmount} currency /></strong>
          <UiButton aria-label="مراجعة السلة والعميل" onClick={() => setIsCartOpen(true)} className="px-2 text-xs"><ShoppingBag className="h-4 w-4" />{formatItemCount(cartItems.length)} · السلة</UiButton>
        </div>
        <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-2">{paymentControl}{completeSaleButton}</div>
      </StickyActionBar>
      {showReceiptModal&&lastInvoice&&<SaleReceiptDialog completed receipt={invoiceReceipt(lastInvoice,receiptBranch)}
        onClose={()=>setShowReceiptModal(false)} onShare={()=>void handleShareReceipt()} onCopy={()=>void handleCopyReceiptLink()}/>}

      {parcelOption && <PosParcelBuilder option={parcelOption}
        initialComponents={(() => {const line = cartItems.find(i => i.id === editingParcelId)?.v2Line;
          return line?.commercial_line_kind === 'configurable_parcel' ? line.parcel_instances[0].components : undefined;})()}
        onClose={() => {setParcelOption(null); setEditingParcelId(null);}} onAdd={addParcel}/>}
      {/* Live Barcode Camera Scanner Modal */}
      {isBarcodeScannerOpen && (
        <Suspense
          fallback={
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-nw-bg/85 p-4" dir="rtl">
              <div className="flex items-center gap-2 rounded-2xl border border-nw-border bg-nw-surface px-4 py-3 text-xs font-bold text-nw-text shadow-2xl">
                <Loader2 className="h-4 w-4 animate-spin text-nw-ok" />
                <span>جاري فتح قارئ الباركود...</span>
              </div>
            </div>
          }
        >
          <BarcodeScannerModal
            isOpen={isBarcodeScannerOpen}
            onClose={() => setIsBarcodeScannerOpen(false)}
            resolveProductCode={resolveScannedProductCode}
            onProductScanned={(scannedProduct) => addToCart(scannedProduct,'legacy_single_sku_parcel','barcode')}
            setToast={setToast}
          />
        </Suspense>
      )}

      <Modal isOpen={isChequeOpen} onClose={()=>setIsChequeOpen(false)} title="استلام شيك عميل" confirmUnsavedClose>
        {isChequeOpen&&selectedPosCustomer&&<ChequeRegistrationForm direction="incoming" partyId={selectedPosCustomer.id}
          parties={[selectedPosCustomer]} branchId={activeBranch?.id??null} onClose={()=>setIsChequeOpen(false)}
          onSaved={result=>{const balance=result.customerBalanceInMinorUnits;if(balance!==null)setPosCustomers(rows=>rows.map(c=>c.id===result.cheque.customerId
            ?{...c,currentBalance:balance/1000}:c));setIsChequeOpen(false);setToast('تم استلام الشيك دون حركة على الدرج.','success');}} />}
      </Modal>
      <Modal
        isOpen={isAddCustomerOpen}
        onClose={() => setIsAddCustomerOpen(false)}
        title="زبون جديد سريع"
        subtitle="سيُحفظ في العملاء ويُختار لهذه الفاتورة مباشرة"
      >
        <AddCustomerModalContent
          quick
          onClose={() => setIsAddCustomerOpen(false)}
          onCreated={handleCustomerCreated}
        />
      </Modal>
    </div>
  );
};

